   Walsh=left@HL[k].T
   for target in list(want):
    for const in (0,1):
     ii,jj=np.where(Walsh==((1-2*const)*(4096-2*target)))
     if not len(ii):continue
     i,j=int(ii[0]),int(jj[0]);h=0;p=0;q=0
